int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    unsigned long start = addr;
    unsigned long next;
    int ret = 0;

    if (!walk) {
        return -EINVAL;
    }

    if (addr >= end) {
        return -EINVAL;
    }

    while (start < end) {
        struct vm_area_struct *vma = find_vma_intersection(current->mm, start, end);
        if (!vma) {
            return -EFAULT;
        }

        if (!(vma->vm_flags & VM_HUGETLB)) {
            return -EINVAL;
        }

        next = start + (1UL << vma->vm_page_shift);
        if (next > end) {
            next = end;
        }

        if (walk->fn) {
            ret = walk->fn(start, next, walk);
            if (ret < 0) {
                break;
            }
        }

        start = next;
    }

    return ret;
}
